    def calculate_tax_C2(ws_calc_amount: Decimal) -> Decimal:
        """Calculate tax based on income brackets."""
        logger.info(f"Calculating tax for amount: {ws_calc_amount}")
    ws_bracket_1_max: Decimal = Decimal('20000.00')
    ws_bracket_1_rate: Decimal = Decimal('0.10')
    ws_bracket_2_max: Decimal = Decimal('50000.00')
    ws_bracket_2_rate: Decimal = Decimal('0.20')
    ws_bracket_3_max: Decimal = Decimal('100000.00')
    ws_bracket_3_rate: Decimal = Decimal('0.30')
    ws_bracket_5_rate: Decimal = Decimal('0.40')

    ws_calc_tax: Decimal = Decimal('0.00')

    if ws_calc_amount <= ws_bracket_1_max:
        ws_calc_tax = ws_calc_amount * ws_bracket_1_rate
    elif ws_calc_amount <= ws_bracket_2_max:
        ws_calc_tax = (ws_bracket_1_max * ws_bracket_1_rate) + \
                      ((ws_calc_amount - ws_bracket_1_max) * ws_bracket_2_rate)
    elif ws_calc_amount <= ws_bracket_3_max:
        ws_calc_tax = (ws_bracket_1_max * ws_bracket_1_rate) + \
                      ((ws_bracket_2_max - ws_bracket_1_max) * ws_bracket_2_rate) + \
                      ((ws_calc_amount - ws_bracket_2_max) * ws_bracket_3_rate)
    else:
        ws_calc_tax = ws_calc_amount * ws_bracket_5_rate

    return ws_calc_tax

