    try:
        customer_file = open(CUSTOMER_FILE_C5, "r") #OPEN INPUT  customer_file
        customer_file.close()
        account_file = open(ACCOUNT_FILE_C5, "r") #OPEN INPUT  account_file
        account_file.close()
        transaction_file = open(TRANSACTION_FILE_C5, "r") #OPEN INPUT  transaction_file
        transaction_file.close()
        report_file = open(REPORT_FILE_C5, "w") #OPEN OUTPUT report_file
        report_file.close()
        error_file = open(ERROR_FILE_C5, "w") #OPEN OUTPUT error_file
        error_file.close()
        master_file = open(MASTER_FILE_C5, "r+") #OPEN I-O    master_file
        master_file.close() # Context manager not useful, opened then closed
        if WS_FILE_STATUS_C5 != '00': #IF ws_file_status NOT = '00'
            WS_ERROR_MSG_C5 = 'FILE OPEN ERROR' #MOVE 'FILE OPEN ERROR' TO ws_error_msg
            abort_process_9500_C5() #PERFORM 9500-abort_process
    except FileNotFoundError as e:
        WS_ERROR_MSG_C5 = f'FILE OPEN ERROR: {e}'
        abort_process_9500_C5()
    except Exception as e:
        WS_ERROR_MSG_C5 = f'FILE OPEN ERROR: {e}'
        abort_process_9500_C5()

