    def load_portfolio_C7(holdings_file_path: str, ws_holdings: List[dict], ws_eof_flag: str, ws_hold_idx: int, ws_holdings_count: int) -> None:
        """Load Portfolio Holdings from File."""
        logger.info("Loading Portfolio Holdings from File")
    try:
        with open(holdings_file_path, "r") as f:
            for line in f:
                holding_record = line.strip().split(',')
                if len(holding_record) != 5:
                    logger.warning(f"Skipping invalid holding record: {holding_record}")
                    continue
                try:
                    hold_symbol = holding_record[0]
                    hold_shares = int(holding_record[1])
                    hold_cost_per_share = Decimal(holding_record[2])
                    hold_current_price = Decimal(holding_record[3])
                    hold_type = holding_record[4]
                    holding = {
                        "hold_symbol": hold_symbol,
                        "hold_shares": hold_shares,
                        "hold_cost_per_share": hold_cost_per_share,
                        "hold_current_price": hold_current_price,
                        "hold_type": hold_type
                    }
                    ws_holdings.append(holding)
                    ws_hold_idx += 1
                except ValueError as e:
                    logger.error(f"Error parsing holding record: {holding_record} - {e}")
                    continue

        ws_holdings_count = len(ws_holdings)
        logger.info(f"Loaded {ws_holdings_count} holdings from file")

    except FileNotFoundError:
        ws_eof_flag = 'Y'
        logger.warning(f"Holdings file not found: {holdings_file_path}")
    except Exception as e:
        logger.error(f"Error loading portfolio: {e}")

